            f_tag = st.m.font(theme.FS_MICRO, 600)
            tw = int(st.m.text_w(it.from_, f_tag)) + 12
            tr = QRect(br.x() - tw - 8, br.y() + 8, tw, 18)
            rounded(p, tr, theme.blend(t.plan_wash, t.canvas), None, 9)
            st.m.draw_text(p, tr.x() + 6, tr.y() + (18 - st.m.line_h(f_tag)) / 2, it.from_, f_tag, QColor(t.plan))
        for r, pm, _src in self.thumbs:
            p.drawPixmap(r.translated(x, y).topLeft(), pm)
        chip_bg = theme.blend(t.fill_2, bg_s)
        f_small = st.m.font(theme.FS_SMALL)
        for r, name in self.chips:
            rr = r.translated(x, y)
            rounded(p, rr, chip_bg, None, theme.R2)
            p.drawPixmap(rr.x() + 10, rr.y() + 7, st.m.icon("paperclip", QColor(t.text_2), 12))
            st.m.draw_text(p, rr.x() + 28, rr.y() + (26 - st.m.line_h(f_small)) / 2, name, f_small, QColor(t.text))
        if self.doc is not None and it.text:
            tx = br.x() + PAD_W
            ty = br.y() + PAD_H + self.attach_h + self._dy
            # clipped to the bubble, not the text box: the centring may move the words into the padding
            clip = QRect(tx, br.y() + 1, br.width() - 2 * PAD_W, br.height() - 2)
            if st.clip is not None:
