    CHILD_INDENT = 0
    __slots__ = (
        "children",
        "fen",
        "open",
        "reveal",
        "head_h",
        "pad_top",
        "pad_bottom",
        "shaped",
        "by_key",
        "first_gap",
    )

    def __init__(self, key: str, head_h: int = 0, pad_top: int = 0, pad_bottom: int = 0, open_: bool = True) -> None:
        super().__init__(key)
