        if not self.children or self.reveal <= 0.0:
            return
        top = base + self.content_top()
        i = self.fen.find(y0 - top)
        n = len(self.children)
        while 0 <= i < n:
            c = self.children[i]
            cy = top + self.fen.prefix(i)
            if cy >= y1:
                break
            if c.h > 0:
                if isinstance(c, Group) and c.children:
