        self.dirty_rects.append((0, b.y(), self.width or 1, b.h))

    def take_dirty(self) -> Tuple[List[Tuple[Block, int]], List[Tuple[int, int, int, int]]]:
        d, r = list(self.dirty.items()), self.dirty_rects
