        super().resizeEvent(e)
        self._place_jump()
        self._place_find()

    def hideEvent(self, e) -> None:
        self._remember()
        super().hideEvent(e)

    def keyPressEvent(self, e) -> None:
        self.view.keyPressEvent(e)
