def _clear(lay) -> None:
    while lay.count():
        it = lay.takeAt(0)
        w = it.widget()
        if w is not None:
            w.hide()
            w.setParent(None)
            w.deleteLater()
        elif it.layout() is not None:
            _clear(it.layout())


# ---------------------------------------------------------------- small parts


class FlowLayout(QLayout):
    """Items left to right, wrapping to the next row when the width runs out (``flex-wrap: wrap``)."""

    def __init__(self, parent: Optional[QWidget] = None, spacing: int = 6) -> None:
        super().__init__(parent)
        self._items: List[Any] = []
        self._gap = spacing
        self.setContentsMargins(0, 0, 0, 0)

    def addItem(self, item) -> None:
        self._items.append(item)

    def count(self) -> int:
        return len(self._items)

    def itemAt(self, i: int):
        return self._items[i] if 0 <= i < len(self._items) else None

    def takeAt(self, i: int):
        return self._items.pop(i) if 0 <= i < len(self._items) else None

    def expandingDirections(self) -> Qt.Orientation:
        return Qt.Orientation(0)

    def hasHeightForWidth(self) -> bool:
        return True

    def heightForWidth(self, w: int) -> int:
        return self._lay(QRect(0, 0, w, 0), True)

    def setGeometry(self, r: QRect) -> None:
        super().setGeometry(r)
        self._lay(r, False)

    def sizeHint(self) -> QSize:
        return self.minimumSize()

    def minimumSize(self) -> QSize:
        s = QSize()
        for it in self._items:
            s = s.expandedTo(it.minimumSize())
        return s

    def _lay(self, r: QRect, test: bool) -> int:
        x, y, row_h = r.x(), r.y(), 0
        for it in self._items:
            w = it.sizeHint().width()
            h = it.sizeHint().height()
            if x + w > r.right() + 1 and row_h > 0:
                x = r.x()
                y += row_h + self._gap
                row_h = 0
            if not test:
                it.setGeometry(QRect(QPoint(x, y), it.sizeHint()))
            x += w + self._gap
            row_h = max(row_h, h)
        return y + row_h - r.y()


class Chip(Box):
    """``.bd-chip``: the state in a pill on the card's first line."""

    WASH = {
        "review": "accent_wash",
        "prompt": "warn_wash",
