        # ---- footer
        self.err = label("", tone="err", size="small", wrap=True)
        self.err.hide()
        self.add_foot(self.err, 1)
        self.keys = QWidget()
        kl = QHBoxLayout(self.keys)
        kl.setContentsMargins(0, 0, 0, 0)
        kl.setSpacing(4)
        kl.addWidget(Keys("Ctrl"))
        kl.addWidget(Keys("Enter"))
