    def eventFilter(self, obj, e) -> bool:
        if obj is self.edit and e.type() == QEvent.Type.KeyPress:
            if e.key() in (Qt.Key.Key_Return, Qt.Key.Key_Enter) and e.modifiers() & Qt.KeyboardModifier.ControlModifier:
                self.commit()
                return True
            if e.key() == Qt.Key.Key_Escape:
                self.cancel_edit()
                return True
        return super().eventFilter(obj, e)

    def _copy_line(self) -> None:
        QGuiApplication.clipboard().setText(f"- {self.n.get('text') or ''}")
        store.toast("The note, as a CLAUDE.md line, copied", "success")

    def start_edit(self) -> None:
