        main = QWidget()
        ml = QVBoxLayout(main)
        ml.setContentsMargins(0, 0, 0, 0)
        ml.setSpacing(1)
        top = QHBoxLayout()
        top.setSpacing(5)
        self.label = lbl(
            str(a.get("label") or f"agent {int(a.get('index') or 0) + 1}"),
            theme.FS_SMALL,
            tone="faint" if st == "queued" else "",
        )
        self.label.setFixedHeight(16)
        top.addWidget(self.label)
        attempt = int(a.get("attempt") or 0)
        if attempt > 1:
