HOST_DATA.mkdir(parents=True, exist_ok=True)
LOG = HOST_STATE / 'host.log'

def log(*a):
    try:
        with open(LOG, 'a') as f:
            f.write(time.strftime('%Y-%m-%d %H:%M:%S') + '  ' + ' '.join(str(x) for x in a) + '\n')
    except Exception:
