    if (wait.id === id) throw new Error('A card cannot wait for itself.');
    clean = { kind: 'session', id: String(wait.id), prompt };
  }
  store.setMeta(id, { wait: clean });
  record(id, { at: Date.now(), kind: 'wait', note: describeWait(clean) });
