      if (m.wait.kind === 'time' && m.wait.at <= now) {
        await wake(id, 'Time came', WAKE_PROMPT.time);
      } else if (m.wait.kind === 'ci' && caps().ci && now - (ciChecked.get(id) || 0) >= CI_POLL_MS) {
        ciChecked.set(id, now);
        const res = await ciResult(m.wait);
        if (res) {
          ciChecked.delete(id);
