  /** @param {string[] | null} [ids] every entry when null */
  async function refresh(ids = null, { force = false } = {}) {
    const todo = all().filter((e) => (!ids || ids.includes(e.id)) && (force || now() - (refreshedAt.get(e.id) || 0) > REFRESH_MS));
