    n: (last?.n || 0) + 1,
    at: Date.now(),
    kind: external ? 'external' : kind,
    tool: tool || null,
    toolUseId: toolUseId || null,
    uuid: msgUuid || null,
    label: label || '',
    commit,
    tree,
    changed,
    files,
    add: files.reduce((s, f) => s + f.add, 0),
    del: files.reduce((s, f) => s + f.del, 0),
