  if (caps.python) {
    proc = spawn(caps.python, [BRIDGE, String(cols), String(rows), ...argv], { cwd, env, stdio: ['pipe', 'pipe', 'pipe', 'pipe'] });
    resizable = true;
  } else if (caps.script) {
    env.COLUMNS = String(cols);
