      e.preventDefault();
      const last = held[held.length - 1];
      removeHeld(sessionId, last.uuid).catch(toasted);
      setText(last.text);
      return;
    }
    if (e.key === 'ArrowUp' && hist.length && (text === '' || histPos >= 0) && ta.current?.selectionStart === 0) {
      e.preventDefault();
