      {suggest.view}
      {held.length > 0 && <QueueTray sessionId={sessionId} held={held} />}
      <div className={`composer mode-${mode}${busy ? ' busy' : ''}`} onClick={(e) => e.target === e.currentTarget && ta.current?.focus()}>
        {attach.view}
