                <button key={id} className="chip tiny rp-alias" title="Remove" onClick={() => save(e.id, { deps: (e.deps || []).filter((x) => x !== id) }).catch(toasted)}>
                  {byId[id]?.name || basename(id)} <X size={10} />
                </button>
              ))}
              <Select label="Add a dependency" value="" options={depOptions} width={200} onChange={(v) => v && save(e.id, { deps: [...(e.deps || []), v] }).catch(toasted)} />
            </div>
          </Field>
          <Field label="Scanned" hint="">
            <div className="row">
              <span className="mono faint ellipsis grow" title={facts(e)}>
                {facts(e)}
              </span>
              <button className="icon-btn sm" title="Read the folder again" aria-label="Read the folder again" onClick={() => call('repos.refresh', { ids: [e.id], force: true }).catch(toasted)}>
                <RefreshCw size={12} />
              </button>
            </div>
          </Field>
        </div>
      )}
    </div>
  );
}

function Field({ label, hint, top, children }: { label: string; hint: string; top?: boolean; children: React.ReactNode }) {
  return (
    <div className={`rp-field${top ? ' top' : ''}`}>
      <div className="rp-field-label">
        <div>{label}</div>
        {hint && <div className="hint">{hint}</div>}
      </div>
      <div className="rp-field-control">{children}</div>
    </div>
  );
}
