  if (!id) return 'Default';
  const m = id.match(/claude-([a-z]+)-(\d+)(?:-(\d+))?/i);
  if (m) return `${m[1][0].toUpperCase()}${m[1].slice(1)} ${m[2]}${m[3] && m[3].length <= 2 ? '.' + m[3] : ''}`;
