  if (fontStyle & 1) s['--shiki-dark-font-style'] = s['--shiki-light-font-style'] = 'italic';
  if (fontStyle & 2) s['--shiki-dark-font-weight'] = s['--shiki-light-font-weight'] = 'bold';
  return s;
}

