let currentBase: string | null = null;
function resolveSrc(src: string): string {
  if (!currentBase || /^(https?:|data:|blob:|\/api\/)/i.test(src) || src.startsWith('/')) return src;
  const abs = `${currentBase.replace(/\/+$/, '')}/${src.replace(/^\.\//, '')}`;
