    .call<DispatchJob[]>('dispatch.list')
    // Disconnected: the board fills in on the reconnect, which asks again.
    .then(
      (lst) => set({ jobs: Object.fromEntries((lst || []).map((j) => [j.id, j])), jobsLoaded: true }),
      () => {},
    );
}
