      t.endTs = ts;
      t.status = classifyResult(t, res);
      this.bump(t);
    }
    if (results.length) return;
    if (parent) return; // a subagent's own prompt; the Agent card already shows it
    const texts: string[] = [];
    const images: string[] = [];
    const files: string[] = [];
    for (const b of content) {
      if (b.type === 'text') {
