  letter-spacing: -0.01em;
}
.dialog-body {
  padding: var(--sp-2_5) var(--sp-5_5) var(--sp-5);
  overflow-y: auto;
  display: grid;
  gap: var(--sp-4_5);
  align-content: start;
}
.dialog-foot {
  display: flex;
  align-items: center;
  gap: var(--sp-2);
  padding: var(--sp-3_5) var(--sp-4_5) var(--sp-4) var(--sp-5_5);
  box-shadow: 0 -1px 0 var(--hair);
}
.err-text {
  font-size: var(--fs-small);
  color: var(--err);
  line-height: 1.45;
}
.confirm-body {
  margin: 0;
  color: var(--text-2);
  line-height: 1.6;
}
.confirm-list {
  margin: -6px 0 0;
  padding: var(--sp-2) var(--sp-3);
  list-style: none;
  border-radius: var(--r-2);
