  font-size: var(--fs-small);
  line-height: 1.75;
  max-height: 220px;
  overflow: auto;
}
.check {
  display: flex;
  align-items: center;
  gap: var(--sp-2_25);
  font-size: var(--fs-ui);
  color: var(--text-2);
  cursor: pointer;
}
.check input {
  width: 15px;
  height: 15px;
  accent-color: var(--text);
}

.chips {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--sp-1_5);
}
.chips-label {
  margin-right: var(--sp-0_5);
  font-size: var(--fs-micro);
  color: var(--text-3);
}
.folder-chip,
.chip {
  display: inline-flex;
  align-items: center;
