}
.pal-label {
  flex: 0 1 auto;
  min-width: 0;
}
.pal-hint {
  flex: 1;
  min-width: 0;
  font-size: var(--fs-small);
  color: var(--text-3);
}
.pal-keys {
  margin-left: auto;
}
.pal-keys kbd {
  height: 18px;
  min-width: 18px;
  font-size: var(--fs-tiny-plus);
  background: transparent;
  box-shadow: inset 0 0 0 1px var(--hair-2);
}

/* shortcuts */
.shortcuts {
  display: grid;
}
.shortcut {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--sp-4);
  padding: var(--sp-2_25) 0;
}
.shortcut + .shortcut {
  box-shadow: 0 -1px 0 var(--hair);
}
.keys {
  display: inline-flex;
  align-items: center;
  gap: var(--sp-0_75);
  white-space: nowrap;
}

/* toasts */
/* Toasts drop in at the top centre, clear of the composer and its send button. */
.toasts {
  position: absolute; /* the corner of the conversation, out of the way of what you are reading */
  right: 16px;
  bottom: calc(var(--composer-h, 0px) + 12px);
  z-index: var(--z-toast);
  display: grid;
  justify-items: end;
  gap: var(--sp-2);
  width: min(380px, calc(100vw - 36px));
  pointer-events: none;
}
.toasts > * {
  pointer-events: auto;
}
.toast {
  display: flex;
  align-items: flex-start;
  gap: var(--sp-2_5);
  max-width: 100%;
  min-height: 40px;
  padding: var(--sp-2_25) var(--sp-1_5) var(--sp-2_25) var(--sp-3_25);
  border-radius: var(--r-5);
  background: var(--glass);
  -webkit-backdrop-filter: var(--glass-blur);
  backdrop-filter: var(--glass-blur);
  box-shadow: var(--shadow-glass);
  font-size: var(--fs-small);
  line-height: 1.45;
}
.toast > .grow {
  padding-top: 1px;
  overflow-wrap: anywhere;
}
.toast > .btn,
.toast > .icon-btn {
  margin-top: -2px;
}
.toast-n {
  flex: none;
  align-self: center;
  padding: 0 var(--sp-1_5);
  border-radius: var(--r-pill);
  font-size: var(--fs-tiny-plus);
  color: var(--text-3);
  background: var(--fill-2);
}

.toast > svg {
  flex: none;
  margin-top: var(--sp-0_5);
}
.toast.success > svg {
  color: var(--ok);
}
.toast.error > svg {
  color: var(--err);
}
.toast.warning > svg {
  color: var(--accent-text);
}
.toast.info > svg {
  color: var(--text-3);
}

/* new-session dialog: options folded behind a one-line summary */
.ns-disclose {
  display: flex;
  align-items: center;
  gap: var(--sp-2);
  width: 100%;
  height: 36px;
  margin: var(--sp-0_5) 0 0;
  padding: 0 var(--sp-2);
  border-radius: var(--r-2);
  color: var(--text-2);
  font-size: var(--fs-ui);
  text-align: left;
}
.ns-disclose:hover {
  background: var(--fill-1);
  color: var(--text);
}
.ns-disclose-chev {
  color: var(--text-3);
  transform: rotate(-90deg);
}
.ns-disclose.open .ns-disclose-chev {
  transform: none;
}
.ns-disclose-title {
  font-weight: 550;
}
.ns-disclose-summary {
  flex: 1;
  min-width: 0;
  color: var(--text-3);
  font-size: var(--fs-small);
}
.ns-options {
  display: grid;
  gap: var(--sp-4_5);
  padding: var(--sp-1_5) 0 var(--sp-0_5);
}
