/* ================================================================ dispatch
   One job across many repositories (DISPATCH.md). The board follows the control room's shapes; the
   job view is one row per repository, the state carried by a glyph and a colour, never by a position;
   the composer is the dialog forms laid out as a page. */
.dispatch {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
}
.dp-body {
  gap: var(--sp-5_5);
}
.dp-form {
  max-width: 920px;
  margin: 0 auto;
  width: 100%;
}
.dp-form > .field + .field,
.dp-form > .ns-two,
.dp-form > .dp-inline,
.dp-form > .dp-box {
  margin-top: 0;
}

/* ---- the job card */
.dp-card {
  gap: var(--sp-2);
}
.dp-line {
  display: flex;
  align-items: center;
  gap: var(--sp-2_5);
  min-width: 0;
}
.dp-name {
  font-weight: 600;
  flex: none;
  max-width: 40%;
}
.dp-scope {
  flex: none;
  font-size: var(--fs-small);
}
.dp-counts {
  flex: none;
  font-size: var(--fs-small);
  color: var(--text-2);
}
.dp-cost {
  flex: none;
  font-size: var(--fs-small);
}
.dp-bar {
  display: flex;
  gap: var(--sp-0_5);
  height: 6px;
  flex: 1 1 120px;
  max-width: 220px;
}
.dp-seg {
  flex: 1;
  border-radius: 2px;
  background: var(--fill-2);
}
.dp-seg.done {
  background: var(--ok);
}
.dp-seg.running,
.dp-seg.preparing {
  background: var(--accent);
}
.dp-seg.needs_action {
  background: var(--warn);
}
.dp-seg.failed {
  background: var(--err);
}
.dp-seg.stopped {
  background: var(--text-3);
}

/* ---- a request waiting, the canary waiting: on the board, wells inside the job's card (the control
   room's `.ovc-well`); in the job view, cards of their own (`.ovc.needs`) */
.ovc-well.dp-ask,
.ovc-well.dp-canary {
  align-items: center;
  gap: var(--sp-2_5);
  padding: var(--sp-1_5) var(--sp-2) var(--sp-1_5) var(--sp-2_5);
}
.ovc-well.dp-ask .ovc-perm-what {
  flex: 1 1 auto;
  white-space: nowrap;
}
.dp-ask-who {
  flex: none;
  font-size: var(--fs-micro);
}
.dp-canary-text b {
  font-weight: 560;
}
.dp-card.needs {
  cursor: pointer;
}
.dp-learn {
  display: flex;
  align-items: center;
  gap: var(--sp-2);
  font-size: var(--fs-small);
}

/* ---- the finished rows: the overview row without its mark column */
.dp-fin {
  width: 100%;
  cursor: pointer;
  grid-template-columns: minmax(0, 1fr) auto;
}

/* ---- the job view */
.status-pill.review,
.status-pill.paused {
  color: var(--text-3);
}
.dp-top {
  display: grid;
  gap: var(--sp-2);
  padding: var(--sp-1_5) var(--sp-5) var(--sp-2);
}
.dp-box {
  display: grid;
  gap: var(--sp-1);
  padding: var(--sp-2_25) var(--sp-3);
  border-radius: var(--r-4);
  background: var(--card);
  box-shadow: inset 0 0 0 0.5px var(--hair);
}
.dp-box-h {
  display: flex;
  align-items: baseline;
  gap: var(--sp-2_5);
  font-size: var(--fs-micro);
  font-weight: 600;
  color: var(--text-3);
  letter-spacing: 0.02em;
}
.dp-box-h b {
  font-size: var(--fs-ui);
  color: var(--text);
}
.dp-brief {
  margin: 0;
  font-size: var(--fs-small);
  line-height: 1.5;
  color: var(--text-2);
  white-space: pre-wrap;
}
.dp-rules {
  font-size: var(--fs-micro);
}
.dp-runs {
  flex: 1;
  min-height: 0;
  overflow: auto;
