}
.dp-word.failed {
  color: var(--err);
}
.dp-word.running,
.dp-word.preparing {
  color: var(--accent-text);
}
.dp-word.needs_action {
  color: var(--warn);
}
.dp-word.queued,
.dp-word.skipped,
.dp-word.stopped {
  color: var(--text-3);
}
.dp-repo {
  font-weight: 500;
}
.dp-now {
  color: var(--text-2);
  max-width: 420px;
}
.dp-now > .ellipsis {
  display: inline-block;
  max-width: 260px;
  vertical-align: middle;
}
.dp-now.ok {
  color: var(--ok);
}
.dp-now.err {
  color: var(--err);
}
.dp-acts {
