  background: var(--text-4);
}
.dp-glyph.done {
  background: var(--ok);
}
.dp-glyph.running,
.dp-glyph.preparing {
  background: var(--accent);
}
.dp-glyph.needs_action {
  background: var(--warn);
}
.dp-glyph.failed {
  background: var(--err);
}
.dp-glyph.stopped {
  background: var(--text-3);
}
.dp-glyph.queued,
.dp-glyph.skipped {
  background: transparent;
  box-shadow: inset 0 0 0 1.5px var(--text-4);
}
.dp-foot {
  display: flex;
  align-items: center;
  gap: var(--sp-2);
  padding: var(--sp-2) var(--sp-5) var(--sp-2_5);
  border-top: 1px solid var(--hair);
  font-size: var(--fs-small);
  color: var(--text-2);
}

/* ---- the composer */
.dp-label-line {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--sp-2_5);
}
.dp-label-line .faint {
  font-size: var(--fs-small);
  font-weight: 400;
}
.dp-form .ns-disclose {
  margin: 0;
}
.dp-options {
  display: grid;
  gap: var(--sp-4_5);
  padding: var(--sp-1_5) var(--sp-2) var(--sp-1);
}
.dp-group {
