  gap: var(--sp-2);
}
.dp-group-h {
  font-size: var(--fs-small);
  font-weight: 600;
  color: var(--text-2);
}
.dp-box.dp-plan {
  padding: var(--sp-2_25) var(--sp-3);
}
.dp-inline {
  display: flex;
  align-items: center;
  gap: var(--sp-2);
  flex-wrap: wrap;
}
.dp-model {
  max-width: 220px;
}
.dp-targets-top {
  display: flex;
