}
.fpick-empty {
  padding: var(--sp-3_5) var(--sp-2_5);
  font-size: var(--fs-small);
}
.fpick-foot {
  display: flex;
  align-items: center;
  gap: var(--sp-1_5);
  padding: var(--sp-1_5) var(--sp-2);
  border-top: 1px solid var(--hair);
}
.fpick .browser {
  margin: 0;
  border: 0;
  border-radius: 0;
}
.fpick .browser-list {
