}
.set-control {
  display: flex;
  justify-content: flex-end;
}
/* Field-like controls fill the column so their left edges line up row to row. */
.set-control > .select-btn,
.set-control > .input {
  flex: 1;
  min-width: 0;
}
.settings-about {
  display: flex;
  align-items: center;
  gap: var(--sp-2);
  padding: var(--sp-3) var(--sp-5_5) var(--sp-3_5);
