  height: 11px;
  border: 1.5px solid var(--fill-3);
  border-top-color: var(--text-2);
}

/* ================================================================ one-click new session */

.side-new-wrap {
  display: flex;
  align-items: center;
  gap: var(--sp-0_5);
}
.side-new-wrap .side-new {
  flex: 1;
  min-width: 0;
}
.side-new-opts {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  border-radius: var(--r-2);
  color: var(--text-3);
  opacity: 0;
}
.side-new-wrap:hover .side-new-opts,
.side-new-opts:focus-visible,
.side-new-opts[aria-expanded='true'] {
  opacity: 1;
}
.side-new-opts:hover {
  background: var(--fill-2);
  color: var(--text);
}

/* sidebar collapse / expand */
.side-collapse {
  color: var(--text-3);
}
.side-collapse:hover,
.side-collapse:focus-visible {
  color: var(--text);
}
.head-sidebar {
  margin-right: var(--sp-1);
}
.welcome {
  position: relative;
}
.welcome > .head-sidebar {
  position: absolute;
  top: 10px;
  left: 12px;
}

/* ================================================================ sidebar pages (control room, inbox) */
.side-pages {
  display: grid;
  gap: 1px;
  margin-top: var(--sp-1);
  padding-top: var(--sp-1_5);
  box-shadow: inset 0 1px 0 var(--hair);
}
.side-page {
  display: flex;
  align-items: center;
  gap: var(--sp-2_25);
  height: 30px;
  padding: 0 var(--sp-2);
  border-radius: var(--r-2);
  color: var(--text-2);
  font-size: var(--fs-ui);
  text-align: left;
}
.side-page:hover {
  background: var(--fill-1);
  color: var(--text);
}
.side-page.on {
  background: var(--fill-2);
  color: var(--text);
}
.side-page-n {
  min-width: 18px;
  height: 18px;
  padding: 0 var(--sp-1_25);
  border-radius: var(--r-pill);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: var(--fs-micro);
  color: var(--text-3);
  background: var(--fill-2);
}
.side-page-n.needs {
  color: var(--accent-ink);
  background: var(--accent-solid);
}
.side-page-n.unread {
  color: var(--text);
  background: var(--fill-3);
}
